const { test, expect } = require('@playwright/test');

test('loads data reliably', async ({ page }) => {
  await page.goto('http://localhost:8080/flaky.html');
  await page.click('#loadBtn');
  const resultLocator = page.locator('#result');
  await resultLocator.waitFor({ state: 'visible' });
  await expect(resultLocator).toHaveText('Data Loaded', { timeout: 10000 });
});
